UPDATE MIG_EXEC_DTL
   SET END_DTM = NOW()
     , EXEC_STAT_CD = '20'
     , ERR_CD = NULL
     , LST_ADJPRN_ID = #{auditId}
     , LST_ADJ_DTM = NOW()
 WHERE EXE_ORD = #{execOrd}
   AND TABLE_OWNER = #{tableOwner}
   AND TABLE_ID = #{tableId}
   AND PROC_ORD = #{procOrd}
   AND JOB_TP_CD = #{jobTypeCode}

